import { canonicalActor } from '../contracts/payment-command.mjs';
const deny=()=>{throw Error('Invalid production capability policy');};
const exact=(v,keys)=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join(',')===keys.sort().join(',');
const text=v=>typeof v==='string'&&v.length>0&&v.length<=256&&v===v.trim()&&!/[\u0000-\u001f\u007f]/.test(v);
/** This private reviewed input is an authorization artifact, not evidence generated by its own hash. */
export function parseBusinessPolicy(raw,environment='prod') {
  if(typeof raw!=='string'||Buffer.byteLength(raw)>65536)deny();let p;try{p=JSON.parse(raw);}catch{deny();}
  if(!exact(p,['schemaVersion','environment','evidenceSha256','members'])||p.schemaVersion!==1||!['dev','prod'].includes(environment)||p.environment!==environment||!/^[a-f0-9]{64}$/.test(p.evidenceSha256)||!Array.isArray(p.members)||!p.members.length||p.members.length>256)deny();
  const ids=new Set(),emails=new Set();
  for(const m of p.members){
    if(!exact(m,['partnerId','loginEmail','partnerRole','capabilities'])||!text(m.partnerId)||!text(m.loginEmail)||m.loginEmail!==m.loginEmail.toLowerCase()||!m.loginEmail.includes('@')||!text(m.partnerRole)||ids.has(m.partnerId)||emails.has(m.loginEmail)
      ||!Array.isArray(m.capabilities)||!m.capabilities.length||new Set(m.capabilities).size!==m.capabilities.length||m.capabilities.some(c=>!['read','command','receipt.read','receipt.write'].includes(c)))deny();
    ids.add(m.partnerId);emails.add(m.loginEmail);Object.freeze(m.capabilities);Object.freeze(m);
  }
  Object.freeze(p.members);return Object.freeze(p);
}
export function createBusinessMembership(config) {
  const allowed=email=>config.policy.members.some(m=>m.loginEmail===email);
  async function member(client,email,capability,expectedId){
    const rows=(await client.query('SELECT "Row ID" AS id,"Partner Role" AS role FROM public."Partners" WHERE lower(btrim("Login Email"))=$1 LIMIT 2',[email])).rows;
    if(rows.length!==1||!rows[0].id||(expectedId!==undefined&&rows[0].id!==expectedId))return null;
    return config.policy.members.find(m=>m.partnerId===rows[0].id&&m.loginEmail===email&&m.partnerRole===rows[0].role&&m.capabilities.includes(capability))??null;
  }
  return {emailAllowed:allowed,
    principalAllowed:p=>p?.ok===true&&typeof p.subject==='string'&&!!p.subject&&typeof p.email==='string'&&allowed(p.email),
    resolveMember:(client,email,id)=>member(client,email,'read',id),
    async resolveActor(client,p,capability){const m=await member(client,p.email,capability);return m?canonicalActor({issuer:config.issuer,subject:p.subject,partnerId:m.partnerId,loginEmail:p.email}):null;},
    member};
}
